  window.qgPosView=v=>{if(!['counter','tables','kitchen','bills','shifts','codes','reports','history','staff'].includes(v))return;if(state.scanBusy&&v!=='counter')return message('รอสแกนรายการปัจจุบันให้เสร็จก่อน');state.view=v;render()};window.qgPosMode=m=>{if(state.scanBusy)return message('รอสแกนรายการปัจจุบันให้เสร็จก่อน');if(state.activeDraft?.items.length)return message('ลบร่างหรือแยกทำร่างใหม่ก่อนเปลี่ยนประเภทบิล');state.mode=m;state.selected=null;state.table=null;state.noTable=false;if(state.activeDraft){state.activeDraft.type=m;state.activeDraft.tableId=null}render()};
